 85→// Load loads the Entire settings from .entire/settings.json,
 86→// then applies any overrides from .entire/settings.local.json if it exists.
 87→// Returns default settings if neither file exists.
 88→// Works correctly from any subdirectory within the repository.
 89→func Load(ctx context.Context) (*EntireSettings, error) {
 90→	// Get absolute paths for settings files
 91→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 92→	if err != nil {
 93→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 94→	}
 95→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 96→	if err != nil {
 97→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 98→	}
 99→
100→	// Load base settings
101→	settings, err := loadFromFile(settingsFileAbs)
102→	if err != nil {
103→		return nil, fmt.Errorf("reading settings file: %w", err)
104→	}
105→
106→	// Apply local overrides if they exist
107→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
108→	if err != nil {
109→		if !os.IsNotExist(err) {
110→			return nil, fmt.Errorf("reading local settings file: %w", err)
111→		}
112→		// Local file doesn't exist, continue without overrides
113→	} else {
114→		if err := mergeJSON(settings, localData); err != nil {
115→			return nil, fmt.Errorf("merging local settings: %w", err)
116→		}
117→	}
118→
119→	return settings, nil
120→}
121→
122→// LoadFromFile loads settings from a specific file path without merging local overrides.
123→// Returns default settings if the file doesn't exist.
124→// Use this when you need to display individual settings files separately.
125→func LoadFromFile(filePath string) (*EntireSettings, error) {
126→	return loadFromFile(filePath)
127→}
128→
129→// loadFromFile loads settings from a specific file path.
130→// Returns default settings if the file doesn't exist.
131→func loadFromFile(filePath string) (*EntireSettings, error) {
132→	settings := &EntireSettings{
133→		Enabled: true, // Default to enabled
134→	}
135→
136→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
137→	if err != nil {
138→		if os.IsNotExist(err) {
139→			return settings, nil
140→		}
141→		return nil, fmt.Errorf("%w", err)
142→	}
143→
144→	dec := json.NewDecoder(bytes.NewReader(data))
145→	dec.DisallowUnknownFields()
146→	if err := dec.Decode(settings); err != nil {
147→		return nil, fmt.Errorf("parsing settings file: %w", err)
148→	}
149→
150→	// Validate commit_linking if set
151→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
152→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
153→	}
154→
155→	return settings, nil
156→}
157→
158→// mergeJSON merges JSON data into existing settings.
159→// Only non-zero values from the JSON override existing settings.
160→func mergeJSON(settings *EntireSettings, data []byte) error {
161→	// First, validate that there are no unknown keys using strict decoding
162→	dec := json.NewDecoder(bytes.NewReader(data))
163→	dec.DisallowUnknownFields()
164→	var temp EntireSettings
165→	if err := dec.Decode(&temp); err != nil {
166→		return fmt.Errorf("parsing JSON: %w", err)
167→	}
168→
169→	// Parse into a map to check which fields are present
170→	var raw map[string]json.RawMessage
171→	if err := json.Unmarshal(data, &raw); err != nil {
172→		return fmt.Errorf("parsing JSON: %w", err)
173→	}
174→
175→	// Override enabled if present
176→	if enabledRaw, ok := raw["enabled"]; ok {
177→		var e bool
178→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
179→			return fmt.Errorf("parsing enabled field: %w", err)
180→		}
181→		settings.Enabled = e
182→	}
183→
184→	// Override local_dev if present
185→	if localDevRaw, ok := raw["local_dev"]; ok {
186→		var ld bool
187→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
188→			return fmt.Errorf("parsing local_dev field: %w", err)
189→		}
190→		settings.LocalDev = ld
191→	}
192→
193→	// Override absolute_git_hook_path if present
194→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
195→		var ahp bool
196→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
197→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
198→		}
199→		settings.AbsoluteGitHookPath = ahp
200→	}
201→
202→	// Override log_level if present and non-empty
203→	if logLevelRaw, ok := raw["log_level"]; ok {
204→		var ll string
205→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
206→			return fmt.Errorf("parsing log_level field: %w", err)
207→		}
208→		if ll != "" {
209→			settings.LogLevel = ll
210→		}
211→	}
212→
213→	// Merge strategy_options if present
214→	if optionsRaw, ok := raw["strategy_options"]; ok {
215→		var opts map[string]any
216→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
217→			return fmt.Errorf("parsing strategy_options field: %w", err)
218→		}
219→		if settings.StrategyOptions == nil {
220→			settings.StrategyOptions = opts
221→		} else {
222→			for k, v := range opts {
223→				settings.StrategyOptions[k] = v
224→			}
225→		}
226→	}
227→
228→	// Override telemetry if present
229→	if telemetryRaw, ok := raw["telemetry"]; ok {
230→		var t bool
231→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
232→			return fmt.Errorf("parsing telemetry field: %w", err)
233→		}
234→		settings.Telemetry = &t
235→	}
236→
237→	// Override commit_linking if present and non-empty
238→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
239→		var cl string
240→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
241→			return fmt.Errorf("parsing commit_linking field: %w", err)
242→		}
243→		if cl != "" {
244→			switch cl {
245→			case CommitLinkingAlways, CommitLinkingPrompt:
246→				settings.CommitLinking = cl
247→			default:
248→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
249→			}
250→		}
251→	}
252→
253→	// Override external_agents if present
254→	if externalAgentsRaw, ok := raw["external_agents"]; ok {
255→		var ea bool
256→		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
257→			return fmt.Errorf("parsing external_agents field: %w", err)
258→		}
259→		settings.ExternalAgents = ea
260→	}
261→
262→	return nil
263→}
