  31→// EnableOptions holds the flags for `entire enable`.
  32→type EnableOptions struct {
  33→	LocalDev            bool
  34→	UseLocalSettings    bool
  35→	UseProjectSettings  bool
  36→	ForceHooks          bool
  37→	SkipPushSessions    bool
  38→	Telemetry           bool
  39→	AbsoluteGitHookPath bool
  40→}
  41→
  42→func newEnableCmd() *cobra.Command {
  43→	var opts EnableOptions
  44→	var ignoreUntracked bool
  45→	var agentName string
  46→
  47→	cmd := &cobra.Command{
  48→		Use:   "enable",
  49→		Short: "Enable Entire in current project",
  50→		Long: `Enable Entire with session tracking for your AI agent workflows.
  51→
  52→Uses the manual-commit strategy, which creates session checkpoints without
  53→modifying your active branch.`,
  54→		RunE: func(cmd *cobra.Command, _ []string) error {
  55→			ctx := cmd.Context()
  56→			// Check if we're in a git repository first - this is a prerequisite error,
  57→			// not a usage error, so we silence Cobra's output and use SilentError
  58→			// to prevent duplicate error output in main.go
  59→			if _, err := paths.WorktreeRoot(ctx); err != nil {
  60→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire enable' from within a git repository.")
  61→				return NewSilentError(errors.New("not a git repository"))
  62→			}
  63→
  64→			if err := validateSetupFlags(opts.UseLocalSettings, opts.UseProjectSettings); err != nil {
  65→				return err
  66→			}
  67→
  68→			// Discover external agent plugins so they appear in agent selection.
  69→			external.DiscoverAndRegister(ctx)
  70→
  71→			// Warn if repo has no commits yet
  72→			if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
  73→				fmt.Fprintln(cmd.OutOrStdout(), "Note: This repository has no commits yet. Entire will be configured, but")
  74→				fmt.Fprintln(cmd.OutOrStdout(), "session checkpoints won't work until you create your first commit.")
  75→				fmt.Fprintln(cmd.OutOrStdout())
  76→			}
  77→
  78→			// Non-interactive mode if --agent flag is provided
  79→			if cmd.Flags().Changed("agent") && agentName == "" {
  80→				printMissingAgentError(cmd.ErrOrStderr())
  81→				return NewSilentError(errors.New("missing agent name"))
  82→			}
  83→
  84→			if agentName != "" {
  85→				ag, err := agent.Get(types.AgentName(agentName))
  86→				if err != nil {
  87→					printWrongAgentError(cmd.ErrOrStderr(), agentName)
  88→					return NewSilentError(errors.New("wrong agent name"))
  89→				}
  90→				// --agent is a targeted operation: set up this specific agent without
  91→				// affecting other agents. Unlike the interactive path, it does not
  92→				// uninstall hooks for other previously-enabled agents.
  93→				return setupAgentHooksNonInteractive(ctx, cmd.OutOrStdout(), ag, opts)
  94→			}
  95→			// Detect or prompt for agents
  96→			agents, err := detectOrSelectAgent(ctx, cmd.OutOrStdout(), nil)
  97→			if err != nil {
  98→				return fmt.Errorf("agent selection failed: %w", err)
  99→			}
 100→
 101→			return runEnableInteractive(ctx, cmd.OutOrStdout(), agents, opts)
 102→		},
 103→	}
