 105→	cmd.Flags().BoolVar(&opts.LocalDev, "local-dev", false, "Use go run instead of entire binary for hooks")
 106→	cmd.Flags().MarkHidden("local-dev") //nolint:errcheck,gosec // flag is defined above
 107→	cmd.Flags().BoolVar(&ignoreUntracked, "ignore-untracked", false, "Commit all new files without tracking pre-existing untracked files")
 108→	cmd.Flags().MarkHidden("ignore-untracked") //nolint:errcheck,gosec // flag is defined above
 109→	cmd.Flags().BoolVar(&opts.UseLocalSettings, "local", false, "Write settings to .entire/settings.local.json instead of .entire/settings.json")
 110→	cmd.Flags().BoolVar(&opts.UseProjectSettings, "project", false, "Write settings to .entire/settings.json even if it already exists")
 111→	cmd.Flags().StringVar(&agentName, "agent", "", "Agent to set up hooks for (e.g., "+strings.Join(agent.StringList(), ", ")+"). Enables non-interactive mode.")
 112→	cmd.Flags().BoolVarP(&opts.ForceHooks, "force", "f", false, "Force reinstall hooks (removes existing Entire hooks first)")
 113→	cmd.Flags().BoolVar(&opts.SkipPushSessions, "skip-push-sessions", false, "Disable automatic pushing of session logs on git push")
 114→	cmd.Flags().BoolVar(&opts.Telemetry, "telemetry", true, "Enable anonymous usage analytics")
 115→	cmd.Flags().BoolVar(&opts.AbsoluteGitHookPath, "absolute-git-hook-path", false, "Embed full binary path in git hooks (for GUI git clients that don't source shell profiles)")
 116→
 117→	// Provide a helpful error when --agent is used without a value
 118→	defaultFlagErr := cmd.FlagErrorFunc()
 119→	cmd.SetFlagErrorFunc(func(c *cobra.Command, err error) error {
 120→		var valErr *pflag.ValueRequiredError
 121→		if errors.As(err, &valErr) && valErr.GetSpecifiedName() == "agent" {
 122→			printMissingAgentError(c.ErrOrStderr())
 123→			return NewSilentError(errors.New("missing agent name"))
 124→		}
 125→		return defaultFlagErr(c, err)
 126→	})
 127→
 128→	// Add subcommands for automation/testing
 129→	cmd.AddCommand(newSetupGitHookCmd())
 130→
 131→	return cmd
 132→}
