 169→// runEnableInteractive runs the interactive enable flow.
 170→// agents must be provided by the caller (via detectOrSelectAgent).
 171→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
 172→	// Uninstall hooks for agents that were previously active but are no longer selected
 173→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 174→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 175→	}
 176→
 177→	// Setup agent hooks for all selected agents
 178→	for _, ag := range agents {
 179→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
 180→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 181→		}
 182→	}
 183→
 184→	// Setup .entire directory
 185→	if _, err := setupEntireDirectory(ctx); err != nil {
 186→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 187→	}
 188→
 189→	// Load existing settings to preserve other options (like strategy_options.push)
 190→	settings, err := LoadEntireSettings(ctx)
 191→	if err != nil {
 192→		// If we can't load, start with defaults
 193→		settings = &EntireSettings{}
 194→	}
 195→	// Update the specific fields
 196→	settings.Enabled = true
 197→	if opts.LocalDev {
 198→		settings.LocalDev = true
 199→	}
 200→	if opts.AbsoluteGitHookPath {
 201→		settings.AbsoluteGitHookPath = true
 202→	}
 203→
 204→	// Set push_sessions option if --skip-push-sessions flag was provided
 205→	if opts.SkipPushSessions {
 206→		if settings.StrategyOptions == nil {
 207→			settings.StrategyOptions = make(map[string]interface{})
 208→		}
 209→		settings.StrategyOptions["push_sessions"] = false
 210→	}
 211→
 212→	// Determine which settings file to write to
 213→	// First run always creates settings.json (no prompt)
 214→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 215→	if err != nil {
 216→		entireDirAbs = paths.EntireDir // Fallback to relative
 217→	}
 218→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
 219→
 220→	if showNotification {
 221→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 222→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 223→	}
 224→
 225→	// Save settings to the appropriate file.
 226→	saveSettings := func() error {
 227→		if shouldUseLocal {
 228→			return SaveEntireSettingsLocal(ctx, settings)
 229→		}
 230→		return SaveEntireSettings(ctx, settings)
 231→	}
 232→	if err := saveSettings(); err != nil {
 233→		return fmt.Errorf("failed to save settings: %w", err)
 234→	}
 235→
 236→	// Use settings values (merged from existing config + flags) for hook installation
 237→	// This ensures re-running `entire enable` without flags preserves existing settings
 238→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 239→		return fmt.Errorf("failed to install git hooks: %w", err)
 240→	}
 241→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 242→	fmt.Fprintln(w, "✓ Hooks installed")
 243→
 244→	configDisplay := configDisplayProject
 245→	if shouldUseLocal {
 246→		configDisplay = configDisplayLocal
 247→	}
 248→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 249→
 250→	// Ask about telemetry consent (only if not already asked)
 251→	fmt.Fprintln(w)
 252→	if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
 253→		return fmt.Errorf("telemetry consent: %w", err)
 254→	}
 255→	// Save again to persist telemetry choice
 256→	if err := saveSettings(); err != nil {
 257→		return fmt.Errorf("failed to save settings: %w", err)
 258→	}
 259→
 260→	if err := strategy.EnsureSetup(ctx); err != nil {
 261→		return fmt.Errorf("failed to setup strategy: %w", err)
 262→	}
 263→
 264→	fmt.Fprintln(w, "\nReady.")
 265→
 266→	return nil
 267→}
