 587→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 588→// If strategyName is provided, it sets the strategy; otherwise uses default.
 589→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
 590→	agentName := ag.Name()
 591→	// Check if agent supports hooks
 592→	hookAgent, ok := agent.AsHookSupport(ag)
 593→	if !ok {
 594→		return fmt.Errorf("agent %s does not support hooks", agentName)
 595→	}
 596→
 597→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 598→
 599→	// Install agent hooks (agent hooks don't depend on settings)
 600→	installedHooks, err := hookAgent.InstallHooks(ctx, opts.LocalDev, opts.ForceHooks)
 601→	if err != nil {
 602→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 603→	}
 604→
 605→	// Setup .entire directory
 606→	if _, err := setupEntireDirectory(ctx); err != nil {
 607→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 608→	}
 609→
 610→	// Load existing settings to preserve other options (like strategy_options.push)
 611→	settings, err := LoadEntireSettings(ctx)
 612→	if err != nil {
 613→		// If we can't load, start with defaults
 614→		settings = &EntireSettings{}
 615→	}
 616→	settings.Enabled = true
 617→	if opts.LocalDev {
 618→		settings.LocalDev = true
 619→	}
 620→	if opts.AbsoluteGitHookPath {
 621→		settings.AbsoluteGitHookPath = true
 622→	}
 623→
 624→	// Set push_sessions option if --skip-push-sessions flag was provided
 625→	if opts.SkipPushSessions {
 626→		if settings.StrategyOptions == nil {
 627→			settings.StrategyOptions = make(map[string]interface{})
 628→		}
 629→		settings.StrategyOptions["push_sessions"] = false
 630→	}
 631→
 632→	// Handle telemetry for non-interactive mode
 633→	// Note: if telemetry is nil (not configured), it defaults to disabled
 634→	if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 635→		f := false
 636→		settings.Telemetry = &f
 637→	}
 638→
 639→	if err := SaveEntireSettings(ctx, settings); err != nil {
 640→		return fmt.Errorf("failed to save settings: %w", err)
 641→	}
 642→
 643→	// Use settings values (merged from existing config + flags) for hook installation
 644→	// This ensures re-running `entire enable --agent X` without flags preserves existing settings
 645→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 646→		return fmt.Errorf("failed to install git hooks: %w", err)
 647→	}
 648→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 649→
 650→	if installedHooks == 0 {
 651→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 652→		if ag.IsPreview() {
 653→			msg += " (Preview)"
 654→		}
 655→		fmt.Fprintf(w, "%s\n", msg)
 656→	} else {
 657→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 658→		if ag.IsPreview() {
 659→			msg += " (Preview)"
 660→		}
 661→		fmt.Fprintf(w, "%s\n", msg)
 662→	}
 663→
 664→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 665→
 666→	if err := strategy.EnsureSetup(ctx); err != nil {
 667→		return fmt.Errorf("failed to setup strategy: %w", err)
 668→	}
 669→
 670→	fmt.Fprintln(w, "\nReady.")
 671→
 672→	return nil
 673→}
