 709→// setupEntireDirectory creates the .entire directory and gitignore.
 710→// Returns true if the directory was created, false if it already existed.
 711→func setupEntireDirectory(ctx context.Context) (bool, error) { //nolint:unparam // already present in codebase
 712→	// Get absolute path for the .entire directory
 713→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 714→	if err != nil {
 715→		entireDirAbs = paths.EntireDir // Fallback to relative
 716→	}
 717→
 718→	// Check if directory already exists
 719→	created := false
 720→	if _, err := os.Stat(entireDirAbs); os.IsNotExist(err) {
 721→		created = true
 722→	}
 723→
 724→	// Create .entire directory
 725→	//nolint:gosec // G301: Project directory needs standard permissions for git
 726→	if err := os.MkdirAll(entireDirAbs, 0o755); err != nil {
 727→		return false, fmt.Errorf("failed to create .entire directory: %w", err)
 728→	}
 729→
 730→	// Create/update .gitignore with all required entries
 731→	if err := strategy.EnsureEntireGitignore(ctx); err != nil {
 732→		return false, fmt.Errorf("failed to setup .gitignore: %w", err)
 733→	}
 734→
 735→	return created, nil
 736→}
