 738→// setupGitHook installs the prepare-commit-msg hook for context trailers.
 739→func setupGitHook(ctx context.Context) error {
 740→	s, err := settings.Load(ctx)
 741→	localDev := err == nil && s.LocalDev
 742→	absoluteHookPath := err == nil && s.AbsoluteGitHookPath
 743→	if _, err := strategy.InstallGitHook(ctx, false, localDev, absoluteHookPath); err != nil {
 744→		return fmt.Errorf("failed to install git hook: %w", err)
 745→	}
 746→	strategy.CheckAndWarnHookManagers(ctx, os.Stderr, localDev, absoluteHookPath)
 747→	return nil
 748→}
