 779→// shellCompletionComment is the comment preceding the completion line
 780→const shellCompletionComment = "# Entire CLI shell completion"
 781→
 782→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 783→var errUnsupportedShell = errors.New("unsupported shell")
 784→
 785→// shellCompletionTarget returns the rc file path and completion lines for the
 786→// user's current shell.
 787→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 788→	home, err := os.UserHomeDir()
 789→	if err != nil {
 790→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 791→	}
 792→
 793→	shell := os.Getenv("SHELL")
 794→	switch {
 795→	case strings.Contains(shell, "zsh"):
 796→		return "Zsh",
 797→			filepath.Join(home, ".zshrc"),
 798→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 799→			nil
 800→	case strings.Contains(shell, "bash"):
 801→		bashRC := filepath.Join(home, ".bashrc")
